class AvangaarScreen extends StatefulWidget{const AvangaarScreen({super.key});@override State<AvangaarScreen> createState()=>_AvangaarScreenState();}
class _AvangaarScreenState extends State<AvangaarScreen>{
 final db=Supabase.instance.client;final search=TextEditingController();List<Map<String,dynamic>> posts=[];Map<String,Map<String,dynamic>> profiles={};String topic='همه',sort='new';bool loading=true;
 String imageUrl(String p)=>db.storage.from('avangaar-images').getPublicUrl(p);
 @override void initState(){super.initState();load();}
 @override void dispose(){search.dispose();super.dispose();}
 Future<void> load()async{setState(()=>loading=true);try{final raw=await db.from('avangaar_posts').select('id,author_id,title,summary,body,image_paths,service_topics,created_at').eq('status','published').order('created_at',ascending:false).limit(100);final rows=List<Map<String,dynamic>>.from(raw);final ids=rows.map((x)=>x['author_id'].toString()).toSet().toList();profiles={};if(ids.isNotEmpty){final p=await db.from('user_profiles').select('user_id,display_name,avatar_url').inFilter('user_id',ids);for(final x in p){profiles[x['user_id'].toString()]=Map<String,dynamic>.from(x);}}final pids=rows.map((x)=>x['id'].toString()).toList();final counts=<String,Map<String,int>>{};if(pids.isNotEmpty){final r=await Future.wait([db.from('avangaar_likes').select('post_id').inFilter('post_id',pids),db.from('avangaar_comments').select('post_id').eq('status','published').inFilter('post_id',pids),db.from('avangaar_views').select('post_id').inFilter('post_id',pids)]);for(var i=0;i<r.length;i++){for(final x in r[i]){final id=x['post_id'].toString();counts.putIfAbsent(id,()=>{'likes':0,'comments':0,'views':0});final k=['likes','comments','views'][i];counts[id]![k]=(counts[id]![k]??0)+1;}}}for(final x in rows){final n=counts[x['id'].toString()]??{};x['likes']=n['likes']??0;x['comments']=n['comments']??0;x['views']=n['views']??0;}if(mounted)setState(()=>posts=rows);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('خطا در دریافت نوشته‌ها: '+e.toString())));}if(mounted)setState(()=>loading=false);}
 @override Widget build(BuildContext context){final c=AppColors.of(context);final q=search.text.trim().toLowerCase();var list=posts.where((p)=>(topic=='همه'||List<String>.from(p['service_topics']??[]).contains(topic))&&(q.isEmpty||(p['title'].toString()+' '+p['summary'].toString()+' '+p['body'].toString()).toLowerCase().contains(q))).toList();if(sort=='popular')list.sort((a,b)=>(b['likes'] as int).compareTo(a['likes'] as int));if(sort=='views')list.sort((a,b)=>(b['views'] as int).compareTo(a['views'] as int));return Directionality(textDirection:TextDirection.rtl,child:Scaffold(backgroundColor:c.background,appBar:AppBar(title:const Text('آوانگار'),backgroundColor:c.background,actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton(onPressed:()=>create(c),backgroundColor:c.primary,child:const Icon(Icons.add_rounded)),body:RefreshIndicator(onRefresh:load,child:CustomScrollView(slivers:[
 SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.all(16),child:Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(borderRadius:BorderRadius.circular(22),gradient:const LinearGradient(colors:[Color(0xFF35266D),Color(0xFF104256)])),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('THE COMMUNITY EDITORIAL SPACE',style:TextStyle(color:Color(0xFF6FE5EC),fontSize:9)),SizedBox(height:8),Text('ایده‌ها، تجربه‌ها و روایت‌ها',style:TextStyle(color:Colors.white,fontSize:21,fontWeight:FontWeight.w900)),Text('نوشته‌های اعضای جامعه؛ مشترک میان وب‌سایت و اپلیکیشن.',style:TextStyle(color:Colors.white70,fontSize:11))])))),
 SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.symmetric(horizontal:16),child:TextField(controller:search,onChanged:(_)=>setState((){}),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'جست‌وجو در آوانگار…')))),
 SliverToBoxAdapter(child:SizedBox(height:52,child:ListView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.symmetric(horizontal:12),children:['همه',...avangaarServices].map((s)=>Padding(padding:const EdgeInsets.symmetric(horizontal:4),child:ChoiceChip(label:Text(s,style:const TextStyle(fontSize:10)),selected:topic==s,onSelected:(_)=>setState(()=>topic=s))).toList()))),
 SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.symmetric(horizontal:18),child:Row(children:[const Expanded(child:Text('نوشته‌های جامعه',style:TextStyle(fontWeight:FontWeight.w800,fontSize:17))),DropdownButton<String>(value:sort,items:const [DropdownMenuItem(value:'new',child:Text('جدیدترین')),DropdownMenuItem(value:'popular',child:Text('محبوب‌ترین')),DropdownMenuItem(value:'views',child:Text('پربازدیدترین'))],onChanged:(v)=>setState(()=>sort=v??'new'))]))),
 if(loading)const SliverFillRemaining(child:Center(child:CircularProgressIndicator()))else if(list.isEmpty)const SliverFillRemaining(child:Center(child:Text('هنوز نوشته‌ای منتشر نشده است.')))else SliverPadding(padding:const EdgeInsets.fromLTRB(14,8,14,90),sliver:SliverList(delegate:SliverChildBuilderDelegate((ctx,i)=>card(c,list[i]),childCount:list.length)))
 ]))));}
 Widget card(AppColors c,Map<String,dynamic> p){final prof=profiles[p['author_id']]??{};final paths=List<String>.from(p['image_paths']??[]);final tags=List<String>.from(p['service_topics']??[]);return InkWell(onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>AvangaarDetailScreen(post:p,profile:prof,imageUrl:imageUrl))).then((_)=>load()),child:Container(margin:const EdgeInsets.only(bottom:13),clipBehavior:Clip.antiAlias,decoration:BoxDecoration(color:c.surface,borderRadius:BorderRadius.circular(20),border:Border.all(color:c.line)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[if(paths.isNotEmpty)Image.network(imageUrl(paths.first),height:165,width:double.infinity,fit:BoxFit.cover,errorBuilder:(_,__,___)=>placeholder())else placeholder(),Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Wrap(spacing:5,children:tags.map((s)=>Chip(label:Text(s,style:const TextStyle(fontSize:9)),visualDensity:VisualDensity.compact)).toList()),Text(p['title']??'',maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:16,fontWeight:FontWeight.w800)),Text(p['summary']??'',maxLines:2,overflow:TextOverflow.ellipsis,style:TextStyle(color:c.muted,fontSize:11)),const SizedBox(height:10),Row(children:[CircleAvatar(radius:12,backgroundImage:(prof['avatar_url']??'').toString().isEmpty?null:NetworkImage(prof['avatar_url']),child:(prof['avatar_url']??'').toString().isEmpty?const Icon(Icons.person,size:13):null),const SizedBox(width:7),Expanded(child:Text(prof['display_name']??'عضو Alishams',style:const TextStyle(fontSize:10))),Text(DateTime.tryParse(p['created_at'].toString())?.toLocal().toString().substring(11,16)??'',style:TextStyle(color:c.muted,fontSize:10))]),const Divider(),Row(children:[Text('♡ '+p['likes'].toString(),style:TextStyle(color:c.muted,fontSize:10)),const SizedBox(width:12),Text('◌ '+p['comments'].toString(),style:TextStyle(color:c.muted,fontSize:10)),const SizedBox(width:12),Text('◉ '+p['views'].toString(),style:TextStyle(color:c.muted,fontSize:10)),const Spacer(),Text('مشاهده نوشته ←',style:TextStyle(color:c.secondary,fontSize:11,fontWeight:FontWeight.w800))])]))])));}
 Widget placeholder()=>Container(height:150,width:double.infinity,decoration:const BoxDecoration(gradient:LinearGradient(colors:[Color(0xFF35266D),Color(0xFF104256)])),child:const Icon(Icons.auto_stories_rounded,size:42,color:Color(0xFF8CE9EF)));
 Future<void> create(AppColors c)async{if(db.auth.currentUser==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('برای انتشار ابتدا وارد حساب کاربری شو.')));return;}await Navigator.push(context,MaterialPageRoute(builder:(_)=>AvangaarComposeScreen(colors:c)));load();}
}

class AvangaarComposeScreen extends StatefulWidget{const AvangaarComposeScreen({super.key,required this.colors});final AppColors colors;@override State<AvangaarComposeScreen> createState()=>_AvangaarComposeScreenState();}
class _AvangaarComposeScreenState extends State<AvangaarComposeScreen>{final db=Supabase.instance.client;final title=TextEditingController(),summary=TextEditingController(),body=TextEditingController();final picker=ImagePicker();List<XFile> images=[];final Set<String> topics={};bool saving=false;@override void dispose(){title.dispose();summary.dispose();body.dispose();super.dispose();}Future<void> pick()async{final x=await picker.pickMultiImage(limit:3,imageQuality:88,maxWidth:2400);if(x.isNotEmpty)setState(()=>images=x.take(3).toList());}
 Future<void> publish()async{final u=db.auth.currentUser;if(u==null)return;if(title.text.trim().length<5||summary.text.trim().length<10||body.text.trim().length<30||topics.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('عنوان، توضیحات، متن و حداقل یک موضوع را کامل کن.')));return;}setState(()=>saving=true);try{final paths=<String>[];for(final x in images){final bytes=await x.readAsBytes();if(bytes.length>8*1024*1024)throw Exception('حجم هر تصویر حداکثر ۸ مگابایت است.');final ext=x.name.toLowerCase().endsWith('.png')?'png':x.name.toLowerCase().endsWith('.webp')?'webp':'jpg';final path=u.id+'/'+DateTime.now().microsecondsSinceEpoch.toString()+'_'+paths.length.toString()+'.'+ext;await db.storage.from('avangaar-images').uploadBinary(path,bytes,fileOptions:FileOptions(contentType:ext=='png'?'image/png':ext=='webp'?'image/webp':'image/jpeg'));paths.add(path);}await db.from('avangaar_posts').insert({'author_id':u.id,'title':title.text.trim(),'summary':summary.text.trim(),'body':body.text.trim(),'image_paths':paths,'service_topics':topics.toList()});if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('نوشته منتشر شد و در وب‌سایت هم نمایش داده می‌شود.')));Navigator.pop(context);}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('انتشار انجام نشد: '+e.toString())));}finally{if(mounted)setState(()=>saving=false);}}
 @override Widget build(BuildContext context){final c=widget.colors;return Directionality(textDirection:TextDirection.rtl,child:Scaffold(backgroundColor:c.background,appBar:AppBar(title:const Text('نوشته تازه'),backgroundColor:c.background),body:ListView(padding:const EdgeInsets.all(17),children:[TextField(controller:title,maxLength:140,decoration:const InputDecoration(labelText:'عنوان')),const SizedBox(height:12),TextField(controller:summary,maxLength:320,maxLines:3,decoration:const InputDecoration(labelText:'توضیحات کوتاه')),const SizedBox(height:12),TextField(controller:body,maxLength:50000,minLines:9,maxLines:20,decoration:const InputDecoration(labelText:'متن کامل نوشته')),const SizedBox(height:15),Row(children:[const Expanded(child:Text('تصاویر (حداکثر ۳ عدد)')),TextButton.icon(onPressed:pick,icon:const Icon(Icons.add_photo_alternate_outlined),label:const Text('انتخاب'))]),if(images.isNotEmpty)Wrap(spacing:8,children:images.map((x)=>Chip(avatar:const Icon(Icons.image),label:Text(x.name,overflow:TextOverflow.ellipsis))).toList()),const SizedBox(height:14),const Text('موضوع (حداکثر ۲ خدمت)'),Wrap(spacing:6,runSpacing:4,children:avangaarServices.map((s)=>FilterChip(label:Text(s,style:const TextStyle(fontSize:10)),selected:topics.contains(s),onSelected:(v)=>setState(()=>v?(topics.length<2?topics.add(s):null):topics.remove(s)))).toList()),const SizedBox(height:20),FilledButton.icon(onPressed:saving?null:publish,icon:const Icon(Icons.publish),label:Text(saving?'در حال انتشار…':'انتشار نوشته'))])));}
}

class AvangaarDetailScreen extends StatefulWidget{const AvangaarDetailScreen({super.key,required this.post,required this.profile,required this.imageUrl});final Map<String,dynamic> post,profile;final String Function(String) imageUrl;@override State<AvangaarDetailScreen> createState()=>_AvangaarDetailScreenState();}
class _AvangaarDetailScreenState extends State<AvangaarDetailScreen>{final db=Supabase.instance.client;final comment=TextEditingController();List<Map<String,dynamic>> comments=[];bool liked=false;int likes=0,views=0,slide=0;bool busy=false;@override void initState(){super.initState();load();}@override void dispose(){comment.dispose();super.dispose();}
 Future<void> load()async{final id=widget.post['id'].toString(),uid=db.auth.currentUser?.id;final viewer=uid??('guest_'+DateTime.now().millisecondsSinceEpoch.toString());await db.from('avangaar_views').upsert({'post_id':id,'viewer_key':viewer,'viewed_on':DateTime.now().toUtc().toIso8601String().substring(0,10)},onConflict:'post_id,viewer_key,viewed_on',ignoreDuplicates:true);final a=await Future.wait([db.from('avangaar_comments').select('id,body,user_id,created_at').eq('post_id',id).eq('status','published').order('created_at'),db.from('avangaar_likes').select('post_id').eq('post_id',id),db.from('avangaar_views').select('post_id').eq('post_id',id),if(uid!=null)db.from('avangaar_likes').select('post_id').eq('post_id',id).eq('user_id',uid)]);if(mounted)setState((){comments=List<Map<String,dynamic>>.from(a[0]);likes=a[1].length;views=a[2].length;liked=uid!=null&&a.length>3&&a[3].isNotEmpty;});}
 Future<void> toggleLike()async{final uid=db.auth.currentUser?.id;if(uid==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('برای لایک وارد حساب کاربری شو.')));return;}if(busy)return;setState(()=>busy=true);try{if(liked){await db.from('avangaar_likes').delete().eq('post_id',widget.post['id']).eq('user_id',uid);}else{await db.from('avangaar_likes').insert({'post_id':widget.post['id'],'user_id':uid});}await load();}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> sendComment()async{final uid=db.auth.currentUser?.id;if(uid==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('برای ثبت دیدگاه وارد حساب کاربری شو.')));return;}if(comment.text.trim().isEmpty)return;await db.from('avangaar_comments').insert({'post_id':widget.post['id'],'user_id':uid,'body':comment.text.trim()});comment.clear();await load();}
 Future<void> reportItem(String type,String id)async{final uid=db.auth.currentUser?.id;if(uid==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('برای گزارش وارد حساب کاربری شو.')));return;}final ctl=TextEditingController();final reason=await showDialog<String>(context:context,builder:(ctx)=>Directionality(textDirection:TextDirection.rtl,child:AlertDialog(title:const Text('گزارش محتوای نامناسب'),content:TextField(controller:ctl,maxLength:500,maxLines:3,decoration:const InputDecoration(hintText:'دلیل گزارش را بنویس…')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('انصراف')),FilledButton(onPressed:()=>Navigator.pop(ctx,ctl.text.trim()),child:const Text('ارسال گزارش'))])));ctl.dispose();if(reason==null||reason.length<3)return;try{await db.from(type=='post'?'avangaar_reports':'avangaar_comment_reports').insert(type=='post'?{'post_id':id,'reporter_id':uid,'reason':reason}:{'comment_id':id,'reporter_id':uid,'reason':reason});if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('گزارش برای بررسی ارسال شد.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('این مورد قبلاً گزارش شده یا ثبت گزارش ممکن نیست.')));}}
 @override Widget build(BuildContext context){final c=AppColors.of(context),paths=List<String>.from(widget.post['image_paths']??[]),tags=List<String>.from(widget.post['service_topics']??[]);return Directionality(textDirection:TextDirection.rtl,child:Scaffold(backgroundColor:c.background,appBar:AppBar(title:const Text('آوانگار'),backgroundColor:c.background,actions:[IconButton(tooltip:'گزارش نوشته',onPressed:()=>reportItem('post',widget.post['id'].toString()),icon:const Icon(Icons.flag_outlined))]),body:ListView(padding:const EdgeInsets.all(17),children:[if(paths.isNotEmpty)Stack(alignment:Alignment.center,children:[ClipRRect(borderRadius:BorderRadius.circular(18),child:Image.network(widget.imageUrl(paths[slide]),height:220,width:double.infinity,fit:BoxFit.cover)),if(paths.length>1)Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[IconButton(onPressed:()=>setState(()=>slide=(slide-1+paths.length)%paths.length),icon:const Icon(Icons.chevron_right,color:Colors.white,size:36)),IconButton(onPressed:()=>setState(()=>slide=(slide+1)%paths.length),icon:const Icon(Icons.chevron_left,color:Colors.white,size:36))])]),Wrap(spacing:5,children:tags.map((x)=>Chip(label:Text(x,style:const TextStyle(fontSize:10)))).toList()),Text(widget.post['title']??'',style:const TextStyle(fontSize:23,fontWeight:FontWeight.w900)),Text(widget.post['summary']??'',style:TextStyle(color:c.muted,height:1.9)),const SizedBox(height:8),Text(widget.profile['display_name']??'عضو Alishams',style:TextStyle(color:c.secondary,fontWeight:FontWeight.w700)),Text('♡ '+likes.toString()+'    ◌ '+comments.length.toString()+'    ◉ '+views.toString(),style:TextStyle(color:c.muted,fontSize:11)),OutlinedButton.icon(onPressed:busy?null:toggleLike,icon:Icon(liked?Icons.favorite:Icons.favorite_border,color:liked?Colors.pink:null),label:Text(liked?'پسندیده شد':'پسندیدن')),const Divider(height:28),SelectableText(widget.post['body']??'',style:const TextStyle(fontSize:14,height:2.3)),const SizedBox(height:25),const Text('دیدگاه‌ها',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),Row(children:[Expanded(child:TextField(controller:comment,decoration:const InputDecoration(hintText:'دیدگاهت را بنویس…'))),IconButton(onPressed:sendComment,icon:Icon(Icons.send,color:c.secondary))]),...comments.map((x)=>ListTile(contentPadding:EdgeInsets.zero,title:const Text('عضو Alishams',style:TextStyle(fontWeight:FontWeight.w700,fontSize:12)),subtitle:Text(x['body']??'',style:const TextStyle(height:1.8)),trailing:IconButton(tooltip:'گزارش دیدگاه',onPressed:()=>reportItem('comment',x['id'].toString()),icon:const Icon(Icons.flag_outlined,size:18))))])));}
}
